/**
 * Benny's Ballista — baked hero models.
 *
 * Generated by Projects\Assets\tools\model_prep.py from ComfyUI/Hunyuan3D
 * output, reviewed, and concatenated here by the same tool's --bake mode. Do
 * not hand-edit; re-run the tool and re-bake instead, or an edit here will
 * silently vanish the next time this file is regenerated.
 *
 * Position + index only, no normals/UVs/material — see model_prep.py's module
 * docstring for why that's enough. RT.art repaints every model at runtime
 * from the active colour palette and adds the same ink outline every
 * procedural block gets, so a model behaves exactly like art.js's other
 * builders once decoded.
 */
RT.models = (function () {
  'use strict';

  const registry = Object.create(null);

  function register(name, payload) { registry[name] = payload; }

  function decodeF32(b64) {
    const bin = atob(b64);
    const buf = new ArrayBuffer(bin.length);
    const bytes = new Uint8Array(buf);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return new Float32Array(buf);
  }
  function decodeIndex(b64, is32) {
    const bin = atob(b64);
    const buf = new ArrayBuffer(bin.length);
    const bytes = new Uint8Array(buf);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return is32 ? new Uint32Array(buf) : new Uint16Array(buf);
  }

  /** BufferGeometry for a registered model, or null if it isn't (yet) baked —
   *  callers fall back to their procedural builder, same convention as every
   *  other "model not approved yet" gap in this game. */
  function geometry(name) {
    const p = registry[name];
    if (!p) return null;
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(decodeF32(p.v), 3));
    geo.setIndex(new THREE.BufferAttribute(decodeIndex(p.i, p.i32), 1));
    // Flat-shaded materials (every paper()/glow() material in this game)
    // derive face normals from screen-space position derivatives and never
    // read this attribute — it exists only so WebGL has something bound.
    geo.computeVertexNormals();
    return geo;
  }

  function has(name) { return !!registry[name]; }

  return { register, geometry, has };
})();

